        break
      case 'ArrowRight':
        if (isFolder && !expanded.has(node.id)) onToggleExpand(node)
        break
      case 'ArrowLeft':
        if (isFolder && expanded.has(node.id)) onToggleExpand(node)
        break
      case 'p':
      case 'P':
        onTogglePin(node)
        break
      default:
        return
    }
