import { expect, type APIRequestContext, type Locator, type Page } from '@playwright/test'

export const COMMITTED_ENTRIES = [
  { source: 'Pi', path: 'skills', kind: 'directory' },
  { source: 'Pi', path: 'skills/review.md', kind: 'file' },
  { source: 'Pi', path: 'workflow.md', kind: 'file' },
  { source: 'Claude', path: 'empty.md', kind: 'file' },
  { source: 'Claude', path: 'subagents', kind: 'directory' },
  { source: 'Claude', path: 'subagents/implementer.md', kind: 'file' },
  { source: 'Claude', path: 'workflow.md', kind: 'file' },
]

/** The API starts alongside Vite; wait until the proxy reaches it before loading the page. */
export async function waitForApi(request: APIRequestContext) {
  await expect.poll(async () => (await request.get('/api/entries')).status(), { timeout: 30_000 }).toBe(200)
}

export async function openGraph(page: Page, path = '/') {
  await page.goto(path)
  await expect(page.locator('.graph-canvas')).toBeVisible()
  await expect(node(page, 'Pi')).toBeVisible()
}

/** A graph node wrapper by id ("Pi", "Pi/skills", "Claude/workflow.md"). */
export function node(page: Page, id: string): Locator {
  return page.locator(`.graph-canvas [data-node-id="${id}"]`)
}

export function nodeBody(page: Page, id: string): Locator {
  return node(page, id).locator('.node-body')
}

export function edge(page: Page, parentId: string, childId: string): Locator {
  return page.locator(`.graph-canvas line[data-edge-parent="${parentId}"][data-edge-child="${childId}"]`)
}

export function expandButton(page: Page, name: string): Locator {
  return page.getByRole('button', { name: `Expand ${name}`, exact: true })
}

export function collapseButton(page: Page, name: string): Locator {
  return page.getByRole('button', { name: `Collapse ${name}`, exact: true })
}

export function currentCrumb(page: Page): Locator {
  return page.getByRole('navigation', { name: 'Breadcrumb' }).locator('[aria-current="page"]')
}

export function folderInfo(page: Page): Locator {
  return page.getByTestId('folder-info')
}

export function visibleNodeIds(page: Page): Promise<string[]> {
  return page.locator('.graph-canvas .node').evaluateAll(elements => elements.map(element => element.getAttribute('data-node-id') ?? ''))
}

/** Drags a node body by a screen offset using real pointer events. */
export async function dragNode(page: Page, id: string, dx: number, dy: number) {
  const box = await nodeBody(page, id).locator('.shape').first().boundingBox()
  if (!box) throw new Error(`Node ${id} has no bounding box`)
  const startX = box.x + box.width / 2
  const startY = box.y + box.height / 2
  await page.mouse.move(startX, startY)
  await page.mouse.down()
  await page.mouse.move(startX + dx / 2, startY + dy / 2, { steps: 5 })
  await page.mouse.move(startX + dx, startY + dy, { steps: 5 })
  await page.mouse.up()
}

export async function nodeCenter(page: Page, id: string) {
  const box = await nodeBody(page, id).locator('.shape').first().boundingBox()
  if (!box) throw new Error(`Node ${id} has no bounding box`)
  return { x: box.x + box.width / 2, y: box.y + box.height / 2 }
}

export async function viewTransform(page: Page): Promise<{ x: number; y: number; k: number }> {
  const transform = await page.locator('.graph-canvas > g').getAttribute('transform')
  const match = /translate\(([-\d.e]+) ([-\d.e]+)\) scale\(([-\d.e]+)\)/.exec(transform ?? '')
  if (!match) throw new Error(`Unexpected transform ${transform}`)
  return { x: Number(match[1]), y: Number(match[2]), k: Number(match[3]) }
}

import { test, expect } from '@playwright/test'
import { execFileSync } from 'node:child_process'
import { fileURLToPath } from 'node:url'

// Runs last (files execute alphabetically on the single worker): the suite must leave fixtures/ untouched.
test('the suite leaves no modified or untracked files under fixtures/', () => {
  const repo = fileURLToPath(new URL('..', import.meta.url))
  const status = execFileSync('git', ['status', '--porcelain', '--untracked-files=all', '--', 'fixtures'], { cwd: repo, encoding: 'utf8' })
  expect(status.trim()).toBe('')
})

import { defineConfig } from '@playwright/test'

export default defineConfig({
  testDir: './tests',
  testMatch: '**/*.spec.ts',
  // Browser tests mutate (and then clean) the shared fixture tree, so they must never run concurrently.
  workers: 1,
  fullyParallel: false,
  use: {
    baseURL: 'http://127.0.0.1:5173',
    browserName: 'chromium',
    // Reduced motion makes the force layout settle synchronously, so nothing waits on animation.
    reducedMotion: 'reduce',
  },
  webServer: {
    command: 'npm run dev',
    url: 'http://127.0.0.1:5173',
    reuseExistingServer: false,
    timeout: 30_000,
  },
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import {
  ancestorIds,
  breadcrumbsFor,
  buildIndex,
  childCounts,
  collapseNode,
  describeCounts,
  folderExists,
  folderToPathname,
  parsePathname,
  pruneIds,
  revealFolder,
  visibleGraph,
  type Entry,
} from '../../src/graph/model.ts'
import { wrapLabel } from '../../src/graph/labels.ts'

const entries: Entry[] = [
  { source: 'Pi', path: 'skills', kind: 'directory' },
  { source: 'Pi', path: 'skills/review.md', kind: 'file' },
  { source: 'Pi', path: 'skills/empty', kind: 'directory' },
  { source: 'Pi', path: 'workflow.md', kind: 'file' },
  { source: 'Pi', path: 'archive.md', kind: 'file' },
  { source: 'Claude', path: 'workflow.md', kind: 'file' },
  { source: 'Claude', path: 'orphan/deeper/note.md', kind: 'file' }, // parents omitted on purpose
]

test('buildIndex creates source roots, implicit parents and ordered children (folders first)', () => {
  const index = buildIndex(entries)
  assert.deepEqual([...index.nodes.keys()].slice(0, 2), ['Pi', 'Claude'])
  assert.deepEqual(index.children.get('Pi')!.map(node => node.name), ['skills', 'archive.md', 'workflow.md'])
  assert.deepEqual(index.children.get('Pi/skills')!.map(node => node.id), ['Pi/skills/empty', 'Pi/skills/review.md'])
  assert.equal(index.nodes.get('Claude/orphan')?.kind, 'directory')
  assert.equal(index.nodes.get('Claude/orphan/deeper/note.md')?.parentId, 'Claude/orphan/deeper')
  assert.equal(index.nodes.get('Claude/orphan/deeper/note.md')?.depth, 3)
  // Same filename in both sources stays distinct.
  assert.notEqual(index.nodes.get('Pi/workflow.md'), index.nodes.get('Claude/workflow.md'))
})

test('visibleGraph reveals immediate children only, with one containment edge per child', () => {
  const index = buildIndex(entries)
  const initial = visibleGraph(index, new Set())
  assert.deepEqual(initial.nodes.map(node => node.id), ['Pi', 'Claude'])
  assert.deepEqual(initial.edges, [])

  const piOpen = visibleGraph(index, new Set(['Pi']))
  assert.deepEqual(piOpen.nodes.map(node => node.id), ['Pi', 'Pi/skills', 'Pi/archive.md', 'Pi/workflow.md', 'Claude'])
  assert.ok(piOpen.edges.every(edge => index.nodes.get(edge.childId)!.parentId === edge.parentId))
  assert.ok(!piOpen.nodes.some(node => node.id === 'Pi/skills/review.md'))

  const deep = visibleGraph(index, new Set(['Pi', 'Pi/skills']))
  assert.ok(deep.nodes.some(node => node.id === 'Pi/skills/review.md'))
  // Expansion state of hidden nodes is ignored until they are visible again.
  const hiddenChild = visibleGraph(index, new Set(['Pi/skills']))
  assert.deepEqual(hiddenChild.nodes.map(node => node.id), ['Pi', 'Claude'])
})

test('collapseNode clears descendants, revealFolder expands the ancestor chain, pruneIds drops stale ids', () => {
  const index = buildIndex(entries)
  const expanded = new Set(['Pi', 'Pi/skills', 'Pi/skills/empty', 'Claude'])
  const collapsed = collapseNode(index, expanded, 'Pi')
  assert.deepEqual([...collapsed], ['Claude'])

  const revealed = revealFolder(index, new Set(['Claude']), { source: 'Pi', path: 'skills/empty' })
  assert.deepEqual([...revealed].sort(), ['Claude', 'Pi', 'Pi/skills', 'Pi/skills/empty'])
  assert.deepEqual(ancestorIds(index.nodes.get('Pi/skills/empty')!), ['Pi', 'Pi/skills'])
  // Files are never expandable.
  assert.deepEqual([...revealFolder(index, new Set(), { source: 'Pi', path: 'workflow.md' })], [])

  const smaller = buildIndex(entries.filter(entry => !entry.path.startsWith('skills')))
  assert.deepEqual([...pruneIds(smaller, expanded)], ['Pi', 'Claude'])
  assert.equal(folderExists(smaller, { source: 'Pi', path: 'skills' }), false)
  assert.equal(folderExists(index, { source: 'Pi', path: 'skills' }), true)
  assert.equal(folderExists(index, { source: 'Pi', path: 'workflow.md' }), false)
  assert.equal(folderExists(index, null), true)
})

test('childCounts and describeCounts', () => {
  const index = buildIndex(entries)
  assert.deepEqual(childCounts(index, 'Pi'), { directories: 1, files: 2 })
  assert.equal(describeCounts(childCounts(index, 'Pi')), '1 folder, 2 Markdown files')
  assert.equal(describeCounts(childCounts(index, 'Pi/skills/empty')), 'This folder is empty.')
})

test('folder URLs encode every segment and round-trip awkward names', () => {
  const awkward = { source: 'Claude' as const, path: 'a b/c#d/e?f/g%h/100%' }
  const pathname = folderToPathname(awkward)
  assert.equal(pathname, '/Claude/a%20b/c%23d/e%3Ff/g%25h/100%25')
  assert.deepEqual(parsePathname(pathname), { kind: 'folder', ref: awkward })
  assert.deepEqual(parsePathname('/'), { kind: 'home' })
  assert.deepEqual(parsePathname('/Pi/'), { kind: 'folder', ref: { source: 'Pi', path: '' } })
  assert.deepEqual(parsePathname('/Nope/x'), { kind: 'unknown-source', name: 'Nope' })
  assert.deepEqual(parsePathname('/Pi/%E0%A4%A'), { kind: 'malformed' })
  assert.equal(folderToPathname(null), '/')
})

test('breadcrumbs start at Home and follow the source and directory segments', () => {
  assert.deepEqual(breadcrumbsFor(null).map(crumb => crumb.label), ['Home'])
  const crumbs = breadcrumbsFor({ source: 'Pi', path: 'skills/deep' })
  assert.deepEqual(crumbs.map(crumb => crumb.label), ['Home', 'Pi', 'skills', 'deep'])
  assert.deepEqual(crumbs.map(crumb => crumb.ref), [null, { source: 'Pi', path: '' }, { source: 'Pi', path: 'skills' }, { source: 'Pi', path: 'skills/deep' }])
})

test('wrapLabel breaks long names at separators and truncates with an ellipsis', () => {
  assert.deepEqual(wrapLabel('review.md'), ['review.md'])
  assert.deepEqual(wrapLabel('release-notes-2026.md'), ['release-notes-', '2026.md'])
  const lines = wrapLabel('a'.repeat(60))
  assert.equal(lines.length, 3)
  assert.ok(lines[2].endsWith('…'))
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { chmod, mkdtemp, mkdir, rm, symlink, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join, resolve } from 'node:path'
import { createApp, defaultFixtureRoot, resolveFixtureRoot } from './app.ts'

const expected = [
  { source: 'Pi', path: 'skills', kind: 'directory' },
  { source: 'Pi', path: 'skills/review.md', kind: 'file' },
  { source: 'Pi', path: 'workflow.md', kind: 'file' },
  { source: 'Claude', path: 'empty.md', kind: 'file' },
  { source: 'Claude', path: 'subagents', kind: 'directory' },
  { source: 'Claude', path: 'subagents/implementer.md', kind: 'file' },
  { source: 'Claude', path: 'workflow.md', kind: 'file' },
]

async function withTempRoot(run: (root: string) => Promise<void>) {
  const root = await mkdtemp(join(tmpdir(), 'md-manager-test-'))
  try {
    await mkdir(join(root, 'pi'))
    await mkdir(join(root, 'claude'))
    await run(root)
  } finally {
    await chmod(join(root, 'pi'), 0o755).catch(() => undefined)
    await rm(root, { recursive: true, force: true })
  }
}

test('lists the committed fixtures as a flat, ordered list of directories and Markdown files', async () => {
  const app = createApp(defaultFixtureRoot)
  try {
    const response = await app.inject('/api/entries')
    assert.equal(response.statusCode, 200)
    assert.deepEqual(response.json(), { entries: expected })
    // Query parameters cannot select a different root or path.
    assert.equal((await app.inject('/api/entries?root=/tmp&path=..')).body, response.body)
    // The previous endpoint is gone.
    assert.equal((await app.inject('/api/files')).statusCode, 404)
  } finally { await app.close() }
})

test('fixture root comes from MD_MANAGER_FIXTURE_ROOT or the repository default', () => {
  assert.equal(resolveFixtureRoot({}), defaultFixtureRoot)
  assert.equal(resolveFixtureRoot({ MD_MANAGER_FIXTURE_ROOT: '   ' }), defaultFixtureRoot)
  assert.equal(resolveFixtureRoot({ MD_MANAGER_FIXTURE_ROOT: 'scratch/root' }), resolve('scratch/root'))
})

test('includes nested and empty directories and uppercase .MD, excludes other files and symlinks', async () => {
  await withTempRoot(async root => {
    await mkdir(join(root, 'pi', 'b-empty'))
    await mkdir(join(root, 'pi', 'a-nested', 'deeper'), { recursive: true })
    await writeFile(join(root, 'pi', 'a-nested', 'deeper', 'NOTE.MD'), '')
    await writeFile(join(root, 'pi', 'a-nested', 'ignored.txt'), 'nope')
    await writeFile(join(root, 'pi', 'a-nested', 'archive.md.bak'), 'nope')
    await writeFile(join(root, 'pi', 'zeta.md'), '')
    await writeFile(join(root, 'outside.md'), 'Not in a source folder')
    await symlink(join(root, 'outside.md'), join(root, 'pi', 'linked.md'))
    await symlink(root, join(root, 'claude', 'linked-directory'))
    await symlink(join(root, 'pi'), join(root, 'claude', 'linked-source'))
    const app = createApp(root)
    try {
      const response = await app.inject('/api/entries')
      assert.equal(response.statusCode, 200)
      assert.deepEqual(response.json(), {
        entries: [
          { source: 'Pi', path: 'a-nested', kind: 'directory' },
          { source: 'Pi', path: 'a-nested/deeper', kind: 'directory' },
          { source: 'Pi', path: 'a-nested/deeper/NOTE.MD', kind: 'file' },
          { source: 'Pi', path: 'b-empty', kind: 'directory' },
          { source: 'Pi', path: 'zeta.md', kind: 'file' },
        ],
      })
    } finally { await app.close() }
  })
})

test('missing, unreadable or symlinked sources fail the whole listing without exposing paths', async () => {
  await withTempRoot(async root => {
    await writeFile(join(root, 'pi', 'keep.md'), '')
    const app = createApp(root)
    try {
      await rm(join(root, 'claude'), { recursive: true })
      const missing = await app.inject('/api/entries')
      assert.equal(missing.statusCode, 500)
      assert.match(missing.json().error, /Unable to read the Claude fixture folder/)
      assert.ok(!missing.body.includes(root))

      await symlink(join(root, 'pi'), join(root, 'claude'))
      const linked = await app.inject('/api/entries')
      assert.equal(linked.statusCode, 500)
      assert.match(linked.json().error, /Claude fixture folder/)

      await rm(join(root, 'claude'))
      await mkdir(join(root, 'claude'))
      if (process.getuid?.() !== 0) {
        await chmod(join(root, 'pi'), 0o000)
        const unreadable = await app.inject('/api/entries')
        assert.equal(unreadable.statusCode, 500)
        assert.match(unreadable.json().error, /Unable to read the Pi fixture folder/)
        assert.ok(!unreadable.body.includes(root))
      }
    } finally { await app.close() }
  })
})

