import { useCallback, useEffect, useRef, useState } from 'react'
import { fileToPathname, sameFileRef, type FileRef } from '../graph/model.ts'
import { DocumentError, fetchDocument, type DocumentErrorKind, type FileDocument } from './api.ts'

export type DocumentState =
  | { status: 'loading'; ref: FileRef }
  | { status: 'ready'; ref: FileRef; document: FileDocument }
  | { status: 'error'; ref: FileRef; kind: DocumentErrorKind; message: string }

type Events = {
  onLoaded?: (document: FileDocument) => void
  onFailed?: (ref: FileRef, kind: DocumentErrorKind) => void
}

/**
 * Loads the document for `ref` whenever it changes. Every request is tied to the ref that started it and
 * cancelled when the ref changes or clears, so a slow response (success or error) can never be shown under
 * another document's identity or reopen a document after navigating away.
 */
export function useDocument(ref: FileRef | null, events: Events = {}): { state: DocumentState | null; retry: () => void } {
  const [state, setState] = useState<DocumentState | null>(null)
  const [attempt, setAttempt] = useState(0)
  const eventsRef = useRef(events)
  useEffect(() => { eventsRef.current = events })
  const key = ref ? fileToPathname(ref) : null

  useEffect(() => {
    if (!ref) {
      setState(null)
      return
    }
    const controller = new AbortController()
    const target = ref
    setState({ status: 'loading', ref: target })
    void (async () => {
      try {
        const document = await fetchDocument(target, controller.signal)
        if (controller.signal.aborted) return
        setState({ status: 'ready', ref: target, document })
        eventsRef.current.onLoaded?.(document)
      } catch (error) {
        if (controller.signal.aborted) return
        const kind = error instanceof DocumentError ? error.kind : 'failed'
        const message = error instanceof DocumentError ? error.message : 'The file could not be loaded.'
        setState({ status: 'error', ref: target, kind, message })
        eventsRef.current.onFailed?.(target, kind)
      }
    })()
    return () => controller.abort()
    // `key` captures the ref's identity; the ref object itself may be recreated on every parse.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, attempt])

  const retry = useCallback(() => setAttempt(previous => previous + 1), [])

  // Never expose a state that belongs to a different document than the one requested.
  const current = state && ref && sameFileRef(state.ref, ref) ? state : ref ? { status: 'loading' as const, ref } : null
  return { state: current, retry }
}
